function normName(raw){
  if(!raw) return '';
  let s = String(raw).toLowerCase();
  s = s.replace(/[.,\-'"()]/g,' ');
  s = s.replace(/\s+/g,' ').trim();
  return s;
}
function bigrams(s){ const out=[]; for(let i=0;i<s.length-1;i++) out.push(s.substring(i,i+2)); return out; }
function diceCoeff(a,b){
  if(!a || !b) return 0;
  const A=bigrams(a), B=bigrams(b);
  if(A.length===0 || B.length===0) return a===b?1:0;
  const mapB={};
  B.forEach(bg=>{ mapB[bg]=(mapB[bg]||0)+1; });
  let matches=0;
  A.forEach(bg=>{ if(mapB[bg]>0){ matches++; mapB[bg]--; } });
  return (2*matches)/(A.length+B.length);
}
const af = it => { const j=(it&&it.json)||{}; return { id:j.id, f:(j.fields||j) }; };
const offers = $('Send Eligible Offers').all().map(af).filter(x=>x.id).map(({id,f})=>({ id, desc: f['Public Product Description']||((f['Brand']||'')+' '+(f['Product Name']||'')), norm: normName((f['Brand']||'')+' '+(f['Product Name']||'')), price: f['Price Per Unit & Case']||'', terms: f['Public Terms']||'', stock: f['Stock Display']||'' }));

const rows = $('Read Requirement Sheet').all().map(it=>it.json);
const results = [];
rows.forEach(row=>{
  const brand = row['Brand']||row['brand']||'';
  const product = row['Product Name']||row['Product']||row['product']||'';
  const qty = row['Quantity']||row['Qty']||row['quantity']||'';
  const wanted = normName(brand+' '+product);
  if(!wanted){ return; }
  let best=null,bestScore=0;
  offers.forEach(o=>{ const s=diceCoeff(wanted,o.norm); if(s>bestScore){bestScore=s;best=o;} });
  if(best && bestScore>=0.6){
    results.push({ requested: (brand+' '+product).trim(), qty, matched:true, matchDesc:best.desc, price:best.price, terms:best.terms, stock:best.stock, score:Math.round(bestScore*100) });
  } else {
    results.push({ requested: (brand+' '+product).trim(), qty, matched:false });
  }
});

const matchedLines = results.filter(r=>r.matched).map(r=> r.requested + (r.qty?(' (qty '+r.qty+')'):'') + ' -> ' + r.matchDesc + ' - ' + r.price + (r.terms?(' - '+r.terms):'') + (r.stock?(' ['+r.stock+']'):''));
const unmatchedLines = results.filter(r=>!r.matched).map(r=> r.requested + (r.qty?(' (qty '+r.qty+')'):''));

return [{ json: {
  matchedCount: matchedLines.length,
  unmatchedCount: unmatchedLines.length,
  matchedText: matchedLines.length ? matchedLines.join('\n') : '(none matched automatically)',
  unmatchedText: unmatchedLines.length ? unmatchedLines.join('\n') : '(none)',
  allRequestedText: results.map(r=>r.requested).join(', ')
} }];
